-- ------------------------------------------------------------------ registrants
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, food_allergy, dietary_pref, registered_at)
SELECT 105400 + ROW_NUMBER() OVER (ORDER BY u.id), 1054, u.id, u.dept,
       IF(u.id = 1001, 'absent', 'attended'),
       IF(u.id = 1001, 0, 1),
       IF(u.id = 1001, NULL, TIMESTAMP('2026-10-12', SEC_TO_TIME(8 * 3600 + 35 * 60 + (u.id % 24) * 60))),
       'onsite',
       CASE u.id WHEN 1003 THEN 'กุ้ง' END,
       CASE u.id WHEN 1006 THEN 'ฮาลาล' END,
       TIMESTAMP('2026-09-28' + INTERVAL (u.id % 13) DAY, '21:05:00')
FROM users u
WHERE u.role = 'student'
  AND u.id % 3 <> 0
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.restored_at IS NULL);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-10-12', r.checked_in_at FROM registrations r WHERE r.event_id = 1054 AND r.checked_in = 1;

-- ------------------------------------------------------------------ SAR with the newsletter as recap poster (set below)
INSERT INTO sar_reports (event_id, report_code, status, created_by, created_at)
VALUES (1054, 'SAR-2569-903', 'final', 2, '2026-10-20 14:00:00');

-- ------------------------------------------------------------------ images
-- Event poster: JPEG, 2048 x 2048 (1:1). Recap: the newsletter, JPEG, A4 portrait.
UPDATE events SET poster_url = 'data:image/jpeg;base64,' WHERE id = 1054;
UPDATE sar_reports SET recap_poster_url = 'data:image/jpeg;base64,' WHERE event_id = 1054;
